css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .52); position: relative; overflow: hidden; }
.loader .mid { position: absolute; left: 0; right: 0; top: 50%; height: 2px; background: color-mix(in srgb, var(--accent) 30%, transparent); }
.loader span { position: absolute; width: 8%; border-radius: 2px; animation: tick-scroll calc(var(--loader-speed) * 3.5) linear infinite; }
.loader span::after { content: ''; position: absolute; left: 38%; top: -28%; width: 24%; height: 156%; background: inherit; }
.loader span:nth-of-type(1) { top: 26%; height: 30%; background: var(--accent); }
.loader span:nth-of-type(2) { top: 42%; height: 24%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * -.5); }
.loader span:nth-of-type(3) { top: 18%; height: 38%; background: var(--accent); animation-delay: calc(var(--loader-speed) * -1); }
.loader span:nth-of-type(4) { top: 34%; height: 20%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * -1.5); }
.loader span:nth-of-type(5) { top: 12%; height: 44%; background: var(--accent); animation-delay: calc(var(--loader-speed) * -2); }
.loader span:nth-of-type(6) { top: 30%; height: 26%; background: var(--accent-2); animation-delay: calc(var(--loader-speed) * -2.5); }
.loader span:nth-of-type(7) { top: 20%; height: 40%; background: var(--accent); animation-delay: calc(var(--loader-speed) * -3); }
@keyframes tick-scroll { from { left: 102%; } to { left: -10%; } }
